        for (int i = 1; i <= n; i++) {
            sum += i;
        }
        return sum;
    }
    static double seriesSum(double n) {
        double sum = 0.0;
        for (int i = 1; i <= (int)n; i++) {
            sum += 1.0 / i;
        }
        return sum;
    }
    static long seriesSum(long n) {
        long sum = 0;
        for (long i = 1; i <= n; i++) {
            sum += (i * i);
        }
        return sum;
    }
    public static void main(String[] args) {
