import java.util.Scanner;
public class BinarySearchExample {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int arr[] = new int[10];
        System.out.println("Enter 10 sorted integer elements in ascending order:");
        for(int i = 0; i < 10; i++) {
            arr[i] = sc.nextInt();
        }
        System.out.println("Enter element to search:");
        int key = sc.nextInt();
        int lb = 0, ub = 9, mid, pos = -1;
        while(lb <= ub) {
            mid = (lb + ub) / 2;
            if(arr[mid] == key) {
                pos = mid;
                break;
            } else if(arr[mid] < key) {
                lb = mid + 1;
            } else {
                ub = mid - 1;
            }
        }
        if(pos != -1) {
            System.out.println("Element found at index: " + pos + " (Position: " + (pos + 1) + ")");
        } else {
            System.out.println("Element not found in the array.");
        }
    }
}

