        int mat[][] = new int[3][3];
        System.out.println("Enter elements for 3x3 matrix:");
        for(int i = 0; i < 3; i++) {
            for(int j = 0; j < 3; j++) {
                mat[i][j] = sc.nextInt();
            }
        }
        int targetSum = 0;
        for(int j = 0; j < 3; j++) {
            targetSum += mat[0][j];
        }
        boolean isMagic = true;
        for(int i = 0; i < 3; i++) {
            int rowSum = 0, colSum = 0;
            for(int j = 0; j < 3; j++) {
                rowSum += mat[i][j];
                colSum += mat[j][i];
            }
            if(rowSum != targetSum || colSum != targetSum) {
                isMagic = false;
                break;
            }
        }
        int diag1 = 0, diag2 = 0;
        for(int i = 0; i < 3; i++) {
            diag1 += mat[i][i];
            diag2 += mat[i][2 - i];
        }
        if(diag1 != targetSum || diag2 != targetSum) {
            isMagic = false;
        }
        if(isMagic) {
            System.out.println("The given matrix is a Magic Square.");
        } else {
