import java.util.Scanner;
public class SortAndBinarySearch {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int arr[] = new int[10];
        System.out.println("Enter 10 distinct integers:");
        for(int i = 0; i < 10; i++) {
            arr[i] = sc.nextInt();
        }
        for(int i = 0; i < 9; i++) {
            for(int j = 0; j < 9 - i; j++) {
                if(arr[j] > arr[j+1]) {
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                }
            }
        }
        System.out.println("Sorted array:");
        for(int i = 0; i < 10; i++) {
            System.out.print(arr[i] + " ");
        }
        System.out.println();
        System.out.println("Enter value to search:");
        int key = sc.nextInt();
        int lb = 0, ub = 9, pos = -1;
        while(lb <= ub) {
            int mid = (lb + ub) / 2;
            if(arr[mid] == key) {
                pos = mid;
                break;
            } else if(arr[mid] < key) {
                lb = mid + 1;
            } else {
                ub = mid - 1;
            }
        }
        if(pos != -1) {
            System.out.println("Element found at index: " + pos);
        } else {
            System.out.println("Element not found.");
        }
    }
}

